// PPOLookback returns how many leading bars [Core.PPO] consumes before its
// first value: called with startIdx 0, its first value is at that bar.
//
// It takes the parameters of [Core.PPO] and returns [BadParam] for one out of
// range.
func (c *Core) PPOLookback(optInFastPeriod, optInSlowPeriod int, optInMAType MAType) (int, error) {
	if !fitsInt32(optInFastPeriod) {
		return 0, BadParam
	}
	if !fitsInt32(optInSlowPeriod) {
		return 0, BadParam
	}
	lookback := c.ppoLookback(int32(optInFastPeriod), int32(optInSlowPeriod), int32(optInMAType))
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

